import { describe, it, expect } from "vitest";
import { englishConfig } from "./english.js";
import { LanguageConfig, computeSonorityLevels, expandClusterConstraintBans, isWholeWordAnchoredSpellingRule, resolveAspirationRules, validateConfig } from "./language.js";
import { VOICED_BONUS, TENSE_BONUS } from "./weights.js";
import { sonorityLevels } from "../elements/phonemes.js";
import { Phoneme } from "../types.js";

describe("LanguageConfig", () => {
  it("should construct a valid English config", () => {
    const config: LanguageConfig = englishConfig;
    expect(config.id).toBe("en");
    expect(config.name).toBe("English");
  });

  describe("phoneme inventory", () => {
    it("should have a non-empty phoneme list", () => {
      expect(englishConfig.phonemes.length).toBeGreaterThan(0);
    });

    it("should have phoneme maps for all syllable positions", () => {
      expect(englishConfig.phonemeMaps.onset.size).toBeGreaterThan(0);
      expect(englishConfig.phonemeMaps.nucleus.size).toBeGreaterThan(0);
      expect(englishConfig.phonemeMaps.coda.size).toBeGreaterThan(0);
    });
  });

  describe("grapheme inventory", () => {
    it("should have a non-empty grapheme list", () => {
      expect(englishConfig.graphemes.length).toBeGreaterThan(0);
    });

    it("should have grapheme maps for all syllable positions", () => {
      expect(englishConfig.graphemeMaps.onset.size).toBeGreaterThan(0);
      expect(englishConfig.graphemeMaps.nucleus.size).toBeGreaterThan(0);
      expect(englishConfig.graphemeMaps.coda.size).toBeGreaterThan(0);
    });
  });

  describe("phonotactic constraints", () => {
    it("should have invalidClusters arrays (may be empty when using feature-based constraints)", () => {
      expect(Array.isArray(englishConfig.invalidClusters.onset)).toBe(true);
      expect(Array.isArray(englishConfig.invalidClusters.coda)).toBe(true);
      expect(Array.isArray(englishConfig.invalidClusters.boundary)).toBe(true);
    });

    it("should store patterns as strings (JSON-serializable)", () => {
      for (const pattern of englishConfig.invalidClusters.onset) {
        expect(typeof pattern).toBe("string");
      }
    });

    it("should expand English boundary cluster rules to the expected banned pairs", () => {
      const expected = new Set([
        // /ŋ/ before anything except /k/, /g/
        "ŋ|p", "ŋ|b", "ŋ|t", "ŋ|d",
        "ŋ|f", "ŋ|v", "ŋ|θ", "ŋ|ð",
        "ŋ|s", "ŋ|z", "ŋ|ʃ", "ŋ|ʒ",
        "ŋ|tʃ", "ŋ|dʒ", "ŋ|m", "ŋ|n",
        "ŋ|l", "ŋ|r", "ŋ|j", "ŋ|w",
        "ŋ|h",
        // /ʒ/ before stops
        "ʒ|p", "ʒ|b", "ʒ|t", "ʒ|d", "ʒ|k", "ʒ|g",
        // /ð/ before stops
        "ð|p", "ð|b", "ð|t", "ð|d", "ð|k", "ð|g",
        // Same-place stop sequences with opposite voicing
        "p|b", "b|p", "t|d", "d|t", "k|g", "g|k",
        // Bilabial nasal + velar stop
        "m|k", "m|g",
      ]);
      const actual = new Set(
        expandClusterConstraintBans(englishConfig).map(([coda, onset]) => `${coda}|${onset}`),
      );
      expect(actual).toEqual(expected);
    });

    it("should auto-ban new non-velar onsets after /ŋ/ while allowing new velar onsets", () => {
      const newPalatalStop: Phoneme = {
        sound: "c",
        mannerOfArticulation: "stop",
        placeOfArticulation: "palatal",
        voiced: false,
        onset: 10,
        coda: 0,
        startWord: 1,
        midWord: 1,
        endWord: 1,
      };
      const newVelarStop: Phoneme = {
        sound: "q",
        mannerOfArticulation: "stop",
        placeOfArticulation: "velar",
        voiced: false,
        onset: 10,
        coda: 0,
        startWord: 1,
        midWord: 1,
        endWord: 1,
      };
      const onsetMap = new Map(englishConfig.phonemeMaps.onset);
      onsetMap.set(newPalatalStop.sound, [newPalatalStop]);
      onsetMap.set(newVelarStop.sound, [newVelarStop]);

      const configWithExtraOnsets: LanguageConfig = {
        ...englishConfig,
        phonemes: [...englishConfig.phonemes, newPalatalStop, newVelarStop],
        phonemeMaps: {
          ...englishConfig.phonemeMaps,
          onset: onsetMap,
        },
      };

      const expanded = new Set(
        expandClusterConstraintBans(configWithExtraOnsets).map(([coda, onset]) => `${coda}|${onset}`),
      );
      expect(expanded.has("ŋ|c")).toBe(true);
      expect(expanded.has("ŋ|q")).toBe(false);
    });
  });

  describe("sonority", () => {
    it("should reference shared weight constants for bonuses", () => {
      expect(englishConfig.sonorityHierarchy.voicedBonus).toBe(VOICED_BONUS);
      expect(englishConfig.sonorityHierarchy.tenseBonus).toBe(TENSE_BONUS);
    });

    it("should compute a level for every phoneme", () => {
      const levels = computeSonorityLevels(englishConfig);
      expect(levels.size).toBe(englishConfig.phonemes.length);
    });

    it("should match the pre-computed sonority levels from phonemes.ts", () => {
      const computed = computeSonorityLevels(englishConfig);
      for (const [phoneme, level] of sonorityLevels) {
        expect(computed.get(phoneme)).toBeCloseTo(level, 10);
      }
    });
  });

  describe("syllable structure", () => {
    it("should have English-appropriate structural limits", () => {
      expect(englishConfig.syllableStructure.maxOnsetLength).toBe(3);
      expect(englishConfig.syllableStructure.maxCodaLength).toBe(4);
      expect(englishConfig.syllableStructure.maxNucleusLength).toBe(1);
    });
  });

  describe("generation weights", () => {
    it("should have onset length distributions", () => {
      const { onsetLength } = englishConfig.generationWeights;
      expect(onsetLength.monosyllabic.length).toBeGreaterThan(0);
      expect(onsetLength.followingNucleus.length).toBeGreaterThan(0);
      expect(onsetLength.default.length).toBeGreaterThan(0);
    });

    it("should have coda length distributions", () => {
      const { codaLength } = englishConfig.generationWeights;
      expect(Object.keys(codaLength.monosyllabic).length).toBeGreaterThan(0);
      expect(codaLength.monosyllabicDefault.length).toBeGreaterThan(0);
      expect(codaLength.polysyllabicNonzero.length).toBeGreaterThan(0);
      expect(codaLength.zeroWeightEndOfWord).toBeGreaterThan(0);
      expect(codaLength.zeroWeightMidWord).toBeGreaterThan(0);
    });

    it("should have probability values between 0 and 100", () => {
      const { probability } = englishConfig.generationWeights;
      for (const [key, value] of Object.entries(probability)) {
        expect(value, key).toBeGreaterThanOrEqual(0);
        expect(value, key).toBeLessThanOrEqual(100);
      }
    });

    it("should have boundary policy values between 0 and 100", () => {
      const { boundaryPolicy } = englishConfig.generationWeights;
      for (const [key, value] of Object.entries(boundaryPolicy)) {
        expect(value, key).toBeGreaterThanOrEqual(0);
        expect(value, key).toBeLessThanOrEqual(100);
      }
    });
  });

  describe("top-down phoneme targeting", () => {
    it("should define phoneme length weights for text and lexicon modes", () => {
      expect(englishConfig.phonemeLengthWeights.text.length).toBeGreaterThan(0);
      expect(englishConfig.phonemeLengthWeights.lexicon.length).toBeGreaterThan(0);
    });

    it("should define phoneme-to-syllable maps for text and lexicon modes", () => {
      expect(Object.keys(englishConfig.phonemeToSyllableWeights.text).length).toBeGreaterThan(0);
      expect(Object.keys(englishConfig.phonemeToSyllableWeights.lexicon).length).toBeGreaterThan(0);
    });
  });

  describe("stress", () => {
    it("should use ot strategy", () => {
      expect(englishConfig.pronunciation.stress.primary.type).toBe("ot");
      expect(englishConfig.pronunciation.stress.primary.otConfig).toBeDefined();
      expect(englishConfig.pronunciation.stress.primary.otConfig!.constraints.length).toBeGreaterThan(0);
    });
  });

  describe("aspiration", () => {
    it("should define English aspiration rules", () => {
      expect(englishConfig.pronunciation.aspiration).toBeDefined();
      expect(englishConfig.pronunciation.aspiration!.targets.length).toBeGreaterThan(0);
      expect(englishConfig.pronunciation.aspiration!.rules.length).toBeGreaterThan(0);
    });

    it("should resolve default aspiration selectors and rules", () => {
      expect(resolveAspirationRules()).toMatchObject({
        enabled: true,
        targets: [
          {
            segment: "onset",
            index: 0,
            manner: ["stop"],
            voiced: false,
          },
        ],
        fallbackProbability: 30,
      });
      expect(resolveAspirationRules().rules.length).toBeGreaterThan(0);
    });
  });
});

describe("morphology config", () => {
  it("should exist and be enabled", () => {
    expect(englishConfig.morphology).toBeDefined();
    expect(englishConfig.morphology!.enabled).toBe(true);
  });

  it("should have 25 suffixes and 8 prefixes", () => {
    expect(englishConfig.morphology!.suffixes).toHaveLength(25);
    expect(englishConfig.morphology!.prefixes).toHaveLength(8);
  });

  it("should have template weights summing to 100 for both modes", () => {
    const { text, lexicon } = englishConfig.morphology!.templateWeights;
    expect(text.bare + text.suffixed + text.prefixed + text.both).toBe(100);
    expect(lexicon.bare + lexicon.suffixed + lexicon.prefixed + lexicon.both).toBe(100);
  });

  it("all affixes should have syllables defined", () => {
    for (const affix of [...englishConfig.morphology!.prefixes, ...englishConfig.morphology!.suffixes]) {
      expect(affix.syllables, `${affix.written} missing syllables`).toBeDefined();
    }
  });

  it("should have allomorphs on -ed and -s", () => {
    const ed = englishConfig.morphology!.suffixes.find(s => s.written === "ed");
    const s = englishConfig.morphology!.suffixes.find(s => s.written === "s");
    expect(ed?.allomorphs).toBeDefined();
    expect(ed!.allomorphs!.length).toBeGreaterThan(0);
    expect(s?.allomorphs).toBeDefined();
    expect(s!.allomorphs!.length).toBeGreaterThan(0);
  });
});

describe("validateConfig", () => {
  it("should pass for the English config", () => {
    expect(() => validateConfig(englishConfig)).not.toThrow();
  });

  it("should reject whole-word anchored spelling rules", () => {
    const bad = {
      ...englishConfig,
      spellingRules: [
        ...(englishConfig.spellingRules ?? []),
        {
          name: "lexical-patch",
          pattern: "^foo$",
          replacement: "bar",
          scope: "word" as const,
        },
      ],
    };
    expect(isWholeWordAnchoredSpellingRule(bad.spellingRules[bad.spellingRules.length - 1])).toBe(true);
    expect(() => validateConfig(bad)).toThrow("must not use whole-word anchored patterns");
  });

  it("should reject whole-word anchored spelling rules that delete the word", () => {
    const bad = {
      ...englishConfig,
      spellingRules: [
        ...(englishConfig.spellingRules ?? []),
        {
          name: "drop-word",
          pattern: "^foo$",
          replacement: "",
          scope: "word" as const,
        },
      ],
    };
    expect(isWholeWordAnchoredSpellingRule(bad.spellingRules[bad.spellingRules.length - 1])).toBe(true);
    expect(() => validateConfig(bad)).toThrow("must not use whole-word anchored patterns");
  });

  it("should allow productive anchored spelling rules with captures", () => {
    const ok = {
      ...englishConfig,
      spellingRules: [
        ...(englishConfig.spellingRules ?? []),
        {
          name: "plural-y-to-ies",
          pattern: "^(.+)y$",
          replacement: "$1ies",
          scope: "word" as const,
        },
      ],
    };
    expect(isWholeWordAnchoredSpellingRule(ok.spellingRules[ok.spellingRules.length - 1])).toBe(false);
    expect(() => validateConfig(ok)).not.toThrow();
  });

  it("should allow anchored spelling rules that use regex syntax", () => {
    const ok = {
      ...englishConfig,
      spellingRules: [
        ...(englishConfig.spellingRules ?? []),
        {
          name: "optional-u",
          pattern: "^colou?r$",
          replacement: "color",
          scope: "word" as const,
        },
      ],
    };
    expect(isWholeWordAnchoredSpellingRule(ok.spellingRules[ok.spellingRules.length - 1])).toBe(false);
    expect(() => validateConfig(ok)).not.toThrow();
  });

  it("should allow weighted gap-spelling variants on the same phoneme sequence", () => {
    const ok = {
      ...englishConfig,
      gapSpellings: [
        ...(englishConfig.gapSpellings ?? []),
        { name: "toe", phonemes: ["t", "u"], replacement: "toe", weight: 5, targetLayer: "grapheme" as const },
      ],
    };
    expect(() => validateConfig(ok)).not.toThrow();
  });

  it("should reject duplicate gap-spelling variants", () => {
    const bad = {
      ...englishConfig,
      gapSpellings: [
        ...(englishConfig.gapSpellings ?? []),
        { name: "duplicate-to", phonemes: ["t", "u"], replacement: "to", targetLayer: "grapheme" as const },
      ],
    };
    expect(() => validateConfig(bad)).toThrow('gapSpellings has duplicate variant for "duplicate-to"');
  });

  it("should reject duplicate gap-spelling variants even when target layers differ", () => {
    const bad = {
      ...englishConfig,
      gapSpellings: [
        ...(englishConfig.gapSpellings ?? []),
        { name: "duplicate-to-layer", phonemes: ["t", "u"], replacement: "to", targetLayer: "spellingRule" as const },
      ],
    };
    expect(() => validateConfig(bad)).toThrow('gapSpellings has duplicate variant for "duplicate-to-layer"');
  });

  it("should reject duplicate gap-spelling variants even when hyphenation differs", () => {
    const bad = {
      ...englishConfig,
      gapSpellings: [
        ...(englishConfig.gapSpellings ?? []),
        {
          name: "duplicate-any-hyphenation",
          phonemes: ["ɛ", "n", "i:"],
          replacement: "any",
          hyphenated: "an&shy;y",
          targetLayer: "grapheme" as const,
        },
      ],
    };
    expect(() => validateConfig(bad)).toThrow(
      'gapSpellings has duplicate variant for "duplicate-any-hyphenation"',
    );
  });

  it("should reject invalid gap-spelling weights", () => {
    const bad = {
      ...englishConfig,
      gapSpellings: [
        ...(englishConfig.gapSpellings ?? []),
        { name: "bad-weight", phonemes: ["t", "u"], replacement: "tow", weight: 0, targetLayer: "grapheme" as const },
      ],
    };
    expect(() => validateConfig(bad)).toThrow("gapSpellings[16].weight must be a finite number > 0");
  });

  it("should reject gap spellings without a target layer", () => {
    const bad = {
      ...englishConfig,
      gapSpellings: [
        ...(englishConfig.gapSpellings ?? []),
        { name: "layerless", phonemes: ["t", "u"], replacement: "teau" } as unknown as NonNullable<typeof englishConfig.gapSpellings>[number],
      ],
    };
    expect(() => validateConfig(bad)).toThrow(
      "gapSpellings[16].targetLayer must be one of grapheme|spellingRule|phonotactics|morphology|unknown",
    );
  });

  it("should reject gap spellings with unknown phonemes", () => {
    const bad = {
      ...englishConfig,
      gapSpellings: [
        ...(englishConfig.gapSpellings ?? []),
        { name: "bad-phoneme", phonemes: ["not-a-phoneme"], replacement: "x", targetLayer: "unknown" as const },
      ],
    };
    expect(() => validateConfig(bad)).toThrow(
      'gapSpellings[16].phonemes[0] contains unknown phoneme "not-a-phoneme"',
    );
  });

  it("should keep the English gap-spelling count on a ratchet", () => {
    expect(englishConfig.gapSpellings).toHaveLength(16);
  });

  it("should throw when a phonemeMap references a phoneme not in phonemes[]", () => {
    const bad = {
      ...englishConfig,
      phonemes: [], // empty — nothing will match
    };
    expect(() => validateConfig(bad)).toThrow("not found in phonemes[]");
  });

  it("should throw when a graphemeMap references a grapheme not in graphemes[]", () => {
    const bad = {
      ...englishConfig,
      graphemes: [], // empty — nothing will match
    };
    expect(() => validateConfig(bad)).toThrow("not found in graphemes[]");
  });

  it("should throw when a probability value is out of range", () => {
    const bad = {
      ...englishConfig,
      generationWeights: {
        ...englishConfig.generationWeights,
        probability: {
          ...englishConfig.generationWeights.probability,
          finalS: 150,
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow("must be in [0, 100]");
  });

  it("should throw when aspiration rule probability is out of range", () => {
    const bad = {
      ...englishConfig,
      pronunciation: {
        ...englishConfig.pronunciation,
        aspiration: {
          ...englishConfig.pronunciation.aspiration!,
          rules: [{ ...englishConfig.pronunciation.aspiration!.rules[0], probability: 101 }],
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow("pronunciation.aspiration.rules[0].probability is 101, must be in [0, 100]");
  });

  it("should throw when aspiration target selector sounds is empty", () => {
    const bad = {
      ...englishConfig,
      pronunciation: {
        ...englishConfig.pronunciation,
        aspiration: {
          ...englishConfig.pronunciation.aspiration!,
          targets: [{ segment: "onset", sounds: [] }],
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow("pronunciation.aspiration.targets[0].sounds must not be empty");
  });

  it("should throw when aspiration target selector uses an unknown onset", () => {
    const bad = {
      ...englishConfig,
      pronunciation: {
        ...englishConfig.pronunciation,
        aspiration: {
          ...englishConfig.pronunciation.aspiration!,
          targets: [{ segment: "onset", sounds: ["not-a-phoneme"] }],
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow('pronunciation.aspiration.targets[0].sounds contains unknown onset phoneme "not-a-phoneme"');
  });

  it("should throw when aspiration target selector uses an unknown nucleus", () => {
    const bad = {
      ...englishConfig,
      pronunciation: {
        ...englishConfig.pronunciation,
        aspiration: {
          ...englishConfig.pronunciation.aspiration!,
          targets: [{ segment: "nucleus", sounds: ["not-a-phoneme"] }],
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow('pronunciation.aspiration.targets[0].sounds contains unknown nucleus phoneme "not-a-phoneme"');
  });

  it("should throw when aspiration previousCodaSounds uses an unknown coda", () => {
    const bad = {
      ...englishConfig,
      pronunciation: {
        ...englishConfig.pronunciation,
        aspiration: {
          ...englishConfig.pronunciation.aspiration!,
          rules: [
            {
              ...englishConfig.pronunciation.aspiration!.rules[0],
              when: { previousCodaSounds: ["not-a-phoneme"] },
            },
          ],
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow('pronunciation.aspiration.rules[0].when.previousCodaSounds contains unknown coda phoneme "not-a-phoneme"');
  });

  it("should throw when pronunciation config is missing", () => {
    const bad = {
      ...englishConfig,
      pronunciation: undefined as unknown as typeof englishConfig.pronunciation,
    };
    expect(() => validateConfig(bad)).toThrow("pronunciation config is required");
  });

  it("should throw when a boundary policy value is out of range", () => {
    const bad = {
      ...englishConfig,
      generationWeights: {
        ...englishConfig.generationWeights,
        boundaryPolicy: {
          ...englishConfig.generationWeights.boundaryPolicy,
          risingCodaDrop: 101,
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow("generationWeights.boundaryPolicy.risingCodaDrop is 101, must be in [0, 100]");
  });

  it("should throw when hiatusPolicy bridge uses unknown phoneme", () => {
    const bad = {
      ...englishConfig,
      hiatusPolicy: {
        ...englishConfig.hiatusPolicy!,
        fallbackBridgeOnsets: [["not-a-phoneme", 100] as [string, number]],
      },
    };
    expect(() => validateConfig(bad)).toThrow("hiatusPolicy.fallbackBridgeOnsets contains unknown phoneme \"not-a-phoneme\"");
  });

  it("should throw when morphology boundary bridge weight is invalid", () => {
    const bad = {
      ...englishConfig,
      morphology: {
        ...englishConfig.morphology!,
        boundaryPolicy: {
          ...englishConfig.morphology!.boundaryPolicy!,
          fallbackBridgeOnsets: [["h", 0] as [string, number]],
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow("morphology.boundaryPolicy.fallbackBridgeOnsets has invalid weight 0 for \"h\" (must be > 0)");
  });

  it("should throw when a morphophonemic rule uses an unknown replacement phoneme", () => {
    const bad = {
      ...englishConfig,
      morphology: {
        ...englishConfig.morphology!,
        suffixes: englishConfig.morphology!.suffixes.map((suffix) =>
          suffix.written === "ity"
            ? {
              ...suffix,
              morphophonemicRules: [
                {
                  name: "bad-replacement",
                  phonologicalCondition: { position: "preceding", place: ["velar"] },
                  replaceSound: "not-a-phoneme",
                },
              ],
            }
            : suffix,
        ),
      },
    };
    expect(() => validateConfig(bad)).toThrow(/morphology\.suffixes\[\d+\]\.morphophonemicRules\[0\]\.replaceSound contains unknown phoneme "not-a-phoneme"/);
  });

  it("should throw when a suffix morphophonemic rule uses following-position conditions", () => {
    const bad = {
      ...englishConfig,
      morphology: {
        ...englishConfig.morphology!,
        suffixes: englishConfig.morphology!.suffixes.map((suffix) =>
          suffix.written === "ity"
            ? {
              ...suffix,
              morphophonemicRules: [
                {
                  name: "bad-position",
                  phonologicalCondition: { position: "following", place: ["velar"] },
                  replaceSound: "s",
                },
              ],
            }
            : suffix,
        ),
      },
    };
    expect(() => validateConfig(bad)).toThrow(/morphology\.suffixes\[\d+\]\.morphophonemicRules\[0\]\.phonologicalCondition\.position must be "preceding" for suffix rules/);
  });

  it("should throw when suffixed template weight is enabled without suffixes", () => {
    const bad = {
      ...englishConfig,
      morphology: {
        ...englishConfig.morphology!,
        suffixes: [],
        templateWeights: {
          text: { bare: 100, suffixed: 0, prefixed: 0, both: 0 },
          lexicon: { bare: 0, suffixed: 100, prefixed: 0, both: 0 },
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow(
      "morphology.templateWeights.lexicon.suffixed requires at least one morphology.suffixes entry",
    );
  });

  it("should throw when both template weight is enabled without prefixes", () => {
    const bad = {
      ...englishConfig,
      morphology: {
        ...englishConfig.morphology!,
        prefixes: [],
        templateWeights: {
          text: { bare: 100, suffixed: 0, prefixed: 0, both: 0 },
          lexicon: { bare: 0, suffixed: 0, prefixed: 100, both: 0 },
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow(
      "morphology.templateWeights.lexicon.prefixed requires at least one morphology.prefixes entry",
    );
  });

  it("should throw when enabled morphology has zero total template weight for a mode", () => {
    const bad = {
      ...englishConfig,
      morphology: {
        ...englishConfig.morphology!,
        templateWeights: {
          text: { bare: 0, suffixed: 0, prefixed: 0, both: 0 },
          lexicon: { ...englishConfig.morphology!.templateWeights.lexicon },
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow(
      "morphology.templateWeights.text must have positive total weight",
    );
  });

  it("should throw when a morphology template weight is negative", () => {
    const bad = {
      ...englishConfig,
      morphology: {
        ...englishConfig.morphology!,
        templateWeights: {
          text: { bare: 100, suffixed: 0, prefixed: -1, both: 0 },
          lexicon: { ...englishConfig.morphology!.templateWeights.lexicon },
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow(
      "morphology.templateWeights.text.prefixed must be a finite number >= 0",
    );
  });

  it("should throw when a morphology template weight is not finite", () => {
    const bad = {
      ...englishConfig,
      morphology: {
        ...englishConfig.morphology!,
        templateWeights: {
          text: { bare: 100, suffixed: 0, prefixed: Number.POSITIVE_INFINITY, both: 0 },
          lexicon: { ...englishConfig.morphology!.templateWeights.lexicon },
        },
      },
    };
    expect(() => validateConfig(bad)).toThrow(
      "morphology.templateWeights.text.prefixed must be a finite number >= 0",
    );
  });

  it("should throw when phonemeLengthWeights.text is missing", () => {
    const bad = {
      ...englishConfig,
      phonemeLengthWeights: {
        ...englishConfig.phonemeLengthWeights,
        text: [],
      },
    };
    expect(() => validateConfig(bad)).toThrow("phonemeLengthWeights.text is required");
  });

  it("should throw when phonemeToSyllableWeights entry is missing for a configured phoneme length", () => {
    const bad = {
      ...englishConfig,
      phonemeToSyllableWeights: {
        ...englishConfig.phonemeToSyllableWeights,
        lexicon: { ...englishConfig.phonemeToSyllableWeights.lexicon, 6: undefined as number[] | undefined },
      },
    };
    expect(() => validateConfig(bad)).toThrow("phonemeToSyllableWeights.lexicon.6 must be a non-empty array");
  });
});

import { Phoneme, Grapheme, GraphemeCondition, Syllable, WordGenerationContext } from "../types.js";
import { LanguageConfig, DoublingConfig, SpellingRule, SilentEConfig, SilentEAppendRule } from "../config/language.js";
import type { RNG } from "../utils/random.js";
import type { TraceCollector, OrthographyTrace, OrthographyUnitTrace, TraceLink, StructuralTrace } from "./trace.js";
import { validateJunction } from "./junction.js";
import getWeightedOption from "../utils/getWeightedOption.js";
import { isVowelChar, isConsonantLetter, VOWEL_LETTERS } from "../utils/letters.js";

// ---------------------------------------------------------------------------
// Spelling rules (config-driven post-processing)
// ---------------------------------------------------------------------------

interface CompiledSpellingRule {
  name: string;
  regex: RegExp;
  replacement: string;
  probability: number;
  scope: "syllable" | "word" | "both";
}

function compileSpellingRules(rules: SpellingRule[]): CompiledSpellingRule[] {
  return rules.map(rule => ({
    name: rule.name,
    regex: new RegExp(rule.pattern, rule.flags ?? "g"),
    replacement: rule.replacement,
    probability: rule.probability ?? 100,
    scope: rule.scope ?? "both",
  }));
}

/**
 * Apply a list of compiled spelling rules to a string, handling probabilistic replacements.
 */
function applySpellingRules(str: string, rules: CompiledSpellingRule[], rand: RNG, trace?: TraceCollector, scope?: string): string {
  let result = str;
  for (const { name, regex, replacement, probability } of rules) {
    regex.lastIndex = 0;
    const before = trace ? result : "";
    if (probability >= 100) {
      result = result.replace(regex, replacement);
    } else {
      result = result.replace(regex, (match, ...args) => {
        if (rand() < probability / 100) {
          let rep = replacement;
          for (let i = 0; i < args.length - 2; i++) {
            if (args[i] !== undefined) {
              rep = rep.replace(`$${i + 1}`, args[i]);
            }
          }
          return rep;
        }
        return match;
      });
    }
    if (trace && result !== before) {
      trace.recordRepair(`spellingRule:${name}`, before, result, scope);
    }
  }
  return result;
}

interface TraceUnitSeed {
  id: number;
  graphemeSelectionIndex: number;
  phoneme: string;
  position: string;
  positionIndex: number;
  syllableIndex: number;
  selected: string;
  emitted: string;
}

type EditOp = "match" | "substitute" | "insert" | "delete";

/**
 * Map character ownership from a source string onto a rewritten target string.
 *
 * Uses edit-distance alignment and propagates ownership through substitutions
 * and insertions so every target character can be highlighted in the debug UI.
 */
function remapOwnersThroughRewrite(source: string, sourceOwners: number[], target: string): number[] {
  if (source === target) return sourceOwners.slice(0, target.length);
  if (target.length === 0) return [];
  if (source.length === 0) return new Array<number>(target.length).fill(-1);

  const m = source.length;
  const n = target.length;
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array<number>(n + 1).fill(0));

  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const substCost = source[i - 1] === target[j - 1] ? 0 : 1;
      const del = dp[i - 1][j] + 1;
      const ins = dp[i][j - 1] + 1;
      const sub = dp[i - 1][j - 1] + substCost;
      dp[i][j] = Math.min(del, ins, sub);
    }
  }

  const ops: EditOp[] = [];
  let i = m;
  let j = n;
  while (i > 0 || j > 0) {
    if (i > 0 && j > 0) {
      const substCost = source[i - 1] === target[j - 1] ? 0 : 1;
      if (dp[i][j] === dp[i - 1][j - 1] + substCost) {
        ops.push(substCost === 0 ? "match" : "substitute");
        i--;
        j--;
        continue;
      }
    }
    if (j > 0 && dp[i][j] === dp[i][j - 1] + 1) {
      ops.push("insert");
      j--;
      continue;
    }
    if (i > 0 && dp[i][j] === dp[i - 1][j] + 1) {
      ops.push("delete");
      i--;
      continue;
    }
    // Defensive fallback for any rare tie/rounding edge.
    if (i > 0 && j > 0) {
      ops.push("substitute");
      i--;
      j--;
    } else if (j > 0) {
      ops.push("insert");
      j--;
    } else {
      ops.push("delete");
      i--;
    }
  }
  ops.reverse();

  const targetOwners = new Array<number>(n).fill(-1);
  let srcIdx = 0;
  let tgtIdx = 0;

  for (const op of ops) {
    if (op === "match" || op === "substitute") {
      targetOwners[tgtIdx] = sourceOwners[srcIdx] ?? -1;
      srcIdx++;
      tgtIdx++;
      continue;
    }
    if (op === "delete") {
      srcIdx++;
      continue;
    }
    // Inserted character: attach to the closest known neighbor owner.
    const leftOwner = tgtIdx > 0 ? targetOwners[tgtIdx - 1] : -1;
    const rightOwner = sourceOwners[srcIdx] ?? -1;
    targetOwners[tgtIdx] = leftOwner !== -1 ? leftOwner : rightOwner;
    tgtIdx++;
  }

  // Fill any unresolved owners by nearest assigned neighbor.
  for (let k = 0; k < targetOwners.length; k++) {
    if (targetOwners[k] !== -1) continue;
    let resolved = -1;
    for (let l = k - 1; l >= 0; l--) {
      if (targetOwners[l] !== -1) {
        resolved = targetOwners[l];
        break;
      }
    }
    if (resolved === -1) {
      for (let r = k + 1; r < targetOwners.length; r++) {
        if (targetOwners[r] !== -1) {
          resolved = targetOwners[r];
          break;
        }
      }
    }
    targetOwners[k] = resolved;
  }

  return targetOwners;
}

function buildLinksForUnit(unit: TraceUnitSeed, trace: TraceCollector): TraceLink[] {
  const links: TraceLink[] = [{
    kind: "graphemeSelection",
    index: unit.graphemeSelectionIndex,
    label: `graphemeSelection:${unit.graphemeSelectionIndex}`,
  }];

  const repNeedles = [unit.emitted, unit.selected].filter(n => !!n && n.length >= 2);
  const hasTokenLike = (text: string, needle: string): boolean => {
    if (!needle || needle.length < 2) return false;
    // Boundaries are start/end or non-letter to reduce accidental substring matches.
    const escaped = needle.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const rx = new RegExp(`(^|[^a-z])${escaped}([^a-z]|$)`, "i");
    return rx.test(text);
  };
  for (let i = 0; i < trace.repairs.length; i++) {
    const r = trace.repairs[i];
    if (repNeedles.some(n => hasTokenLike(r.before, n) || hasTokenLike(r.after, n))) {
      links.push({ kind: "repair", index: i, label: r.rule });
    }
  }

  for (let i = 0; i < trace.structural.length; i++) {
    const s = trace.structural[i];
    if (structuralEventReferencesUnit(s, unit)) {
      links.push({ kind: "structural", index: i, label: s.event });
    }
  }

  return links;
}

function structuralEventReferencesUnit(event: StructuralTrace, unit: TraceUnitSeed): boolean {
  switch (event.event) {
  case "boundaryDrop":
    // Dropped-coda segment is removed pre-orthography; link only the onset-side survivor.
    return unit.position === "onset" &&
      unit.syllableIndex === event.rightSyllableIndex &&
      unit.phoneme === event.beforeOnset;
  case "sspBoundaryDrop":
    return (unit.position === "coda" &&
      unit.syllableIndex === event.leftSyllableIndex &&
      event.remainingCoda.includes(unit.phoneme)) ||
      (unit.position === "onset" &&
      unit.syllableIndex === event.rightSyllableIndex &&
      event.onset.includes(unit.phoneme));
  case "risingCodaBoundaryDrop":
  case "junctionBoundaryDrop":
    return (unit.position === "coda" &&
      unit.syllableIndex === event.leftSyllableIndex &&
      event.remainingCoda.includes(unit.phoneme)) ||
      (unit.position === "onset" &&
      unit.syllableIndex === event.rightSyllableIndex &&
      event.onset.includes(unit.phoneme));
  case "finalS":
    return unit.position === "coda" &&
      unit.syllableIndex === event.syllableIndex &&
      unit.phoneme === "s";
  case "nasalStopExtension":
    return unit.position === "coda" &&
      unit.syllableIndex === event.syllableIndex &&
      (unit.phoneme === event.nasal || unit.phoneme === event.appendedStop);
  case "vowelHiatusFallback":
    return unit.position === "onset" &&
      unit.syllableIndex === event.rightSyllableIndex &&
      unit.phoneme === event.inserted;
  case "morphPrefixHiatusFallback":
  case "morphSuffixHiatusFallback":
    return unit.position === "onset" &&
      unit.syllableIndex === event.syllableIndex &&
      unit.phoneme === event.inserted;
  case "aspirationDecision":
    if (!event.targetPhoneme) return false;
    return unit.position === (event.targetSegment ?? "onset") &&
      unit.syllableIndex === event.syllableIndex &&
      (event.targetIndex == null || unit.positionIndex === event.targetIndex) &&
      unit.phoneme === event.targetPhoneme;
  }
}

function buildOrthographyTrace(
  surface: string,
  finalOwners: number[],
  units: TraceUnitSeed[],
  trace: TraceCollector,
): OrthographyTrace {
  const unitById = new Map<number, TraceUnitSeed>(units.map(u => [u.id, u]));
  const spans = new Map<number, { start: number; end: number }>();
  for (let i = 0; i < finalOwners.length; i++) {
    const owner = finalOwners[i];
    if (!unitById.has(owner)) continue;
    const existing = spans.get(owner);
    if (!existing) {
      spans.set(owner, { start: i, end: i });
    } else {
      existing.end = i;
    }
  }

  const chars = surface.split("").map((char, index) => {
    const unitId = finalOwners[index] ?? -1;
    const owner = unitById.get(unitId);
    return {
      index,
      char,
      unitId,
      graphemeSelectionIndex: owner ? owner.graphemeSelectionIndex : -1,
    };
  });

  const toUnitTrace = (unit: TraceUnitSeed): OrthographyUnitTrace => {
    const span = spans.get(unit.id);
    return {
      id: unit.id,
      graphemeSelectionIndex: unit.graphemeSelectionIndex,
      phoneme: unit.phoneme,
      position: unit.position,
      syllableIndex: unit.syllableIndex,
      selected: unit.selected,
      emitted: unit.emitted,
      present: !!span,
      start: span ? span.start : null,
      end: span ? span.end : null,
      links: buildLinksForUnit(unit, trace),
    };
  };

  const graphemeUnits = units.map(toUnitTrace);
  return { surface, chars, graphemeUnits };
}

export function rewriteOrthographyTraceSurface(trace: TraceCollector, surface: string): void {
  const orthography = trace.orthographyTrace;
  if (!orthography) return;

  const unitById = new Map<number, OrthographyUnitTrace>(
    orthography.graphemeUnits.map((unit) => [unit.id, unit]),
  );
  const sourceOwners = orthography.chars.map((char) => char.unitId);
  const remappedOwners = remapOwnersThroughRewrite(orthography.surface, sourceOwners, surface);
  const spans = new Map<number, { start: number; end: number }>();

  for (let i = 0; i < remappedOwners.length; i++) {
    const owner = remappedOwners[i];
    if (!unitById.has(owner)) continue;
    const span = spans.get(owner);
    if (span) {
      span.end = i;
    } else {
      spans.set(owner, { start: i, end: i });
    }
  }

  orthography.surface = surface;
  orthography.chars = surface.split("").map((char, index) => {
    const unitId = remappedOwners[index] ?? -1;
    const unit = unitById.get(unitId);
    return {
      index,
      char,
      unitId,
      graphemeSelectionIndex: unit?.graphemeSelectionIndex ?? -1,
    };
  });
  orthography.graphemeUnits = orthography.graphemeUnits.map((unit) => {
    const span = spans.get(unit.id);
    return {
      ...unit,
      present: !!span,
      start: span ? span.start : null,
      end: span ? span.end : null,
    };
  });
}

// ---------------------------------------------------------------------------
// Context conditioning
// ---------------------------------------------------------------------------

/**
 * Build category shorthand → Set<string> maps from a phoneme inventory.
 */
function buildCategorySets(phonemes: Phoneme[]): Map<string, Set<string>> {
  const categories = new Map<string, Set<string>>();
  categories.set("lax-vowel", new Set());
  categories.set("tense-vowel", new Set());
  categories.set("front-vowel", new Set());
  categories.set("back-vowel", new Set());
  categories.set("c-soft-vowel", new Set());
  categories.set("vowel", new Set());
  categories.set("consonant", new Set());

  for (const p of phonemes) {
    const isVowel =
      p.mannerOfArticulation === "highVowel" ||
      p.mannerOfArticulation === "midVowel" ||
      p.mannerOfArticulation === "lowVowel";

    if (isVowel) {
      categories.get("vowel")!.add(p.sound);
      if (p.tense === false) categories.get("lax-vowel")!.add(p.sound);
      if (p.tense === true) categories.get("tense-vowel")!.add(p.sound);
      if (p.placeOfArticulation === "front") categories.get("front-vowel")!.add(p.sound);
      // (Triphthongs removed — /aɪə/ decomposed into diphthong + /ə/.)
      if (p.placeOfArticulation === "back") categories.get("back-vowel")!.add(p.sound);
      // Vowels that cause c-softening: front vowels that typically write as e/i/y.
      // Schwa excluded: it often writes as a/o/u where c should be hard (canal, collect).
      const cSoftSounds = new Set(["i:", "ɪ", "ɛ", "eɪ", "aɪ", "ɜ", "ɚ"]);
      if (cSoftSounds.has(p.sound)) categories.get("c-soft-vowel")!.add(p.sound);
    } else {
      categories.get("consonant")!.add(p.sound);
    }
  }

  return categories;
}

/**
 * Expand a context list (which may contain category shorthands) into a Set of phoneme sounds.
 */
function expandContext(ctx: string[], categories: Map<string, Set<string>>): Set<string> {
  const result = new Set<string>();
  for (const item of ctx) {
    const cat = categories.get(item);
    if (cat) {
      for (const s of cat) result.add(s);
    } else {
      result.add(item);
    }
  }
  return result;
}

// ---------------------------------------------------------------------------
// Pre-expanded conditions (Refactor 4)
// ---------------------------------------------------------------------------

interface PreExpandedCondition {
  leftContext?: Set<string>;
  rightContext?: Set<string>;
  notLeftContext?: Set<string>;
  notRightContext?: Set<string>;
  leftGraphemeContext?: Set<string>;
  notLeftGraphemeContext?: Set<string>;
  wordPosition?: ("initial" | "medial" | "final")[];
  syllableShape?: GraphemeCondition["syllableShape"];
}

function mergeSyllableShape(
  aliasShape: GraphemeCondition["syllableShape"],
  explicitShape: GraphemeCondition["syllableShape"],
): GraphemeCondition["syllableShape"] {
  if (!aliasShape && !explicitShape) return undefined;
  return {
    ...(aliasShape ?? {}),
    ...(explicitShape ?? {}),
  };
}

/**
 * Resolve an alias-backed grapheme condition into a plain condition object.
 * Explicit grapheme condition fields override alias-provided defaults.
 */
export function normalizeGraphemeCondition(
  condition: GraphemeCondition | undefined,
  aliases: LanguageConfig["graphemeConditionAliases"] | undefined,
  graphemeForm?: string,
): Omit<GraphemeCondition, "alias"> | undefined {
  if (!condition) return undefined;
  let aliasCondition: Omit<GraphemeCondition, "alias"> | undefined;
  if (condition.alias) {
    aliasCondition = aliases?.[condition.alias];
    if (!aliasCondition) {
      const suffix = graphemeForm ? ` for grapheme "${graphemeForm}"` : "";
      throw new Error(`Unknown grapheme condition alias "${condition.alias}"${suffix}`);
    }
  }

  const { alias, syllableShape: explicitSyllableShape, ...explicitFields } = condition;
  void alias;
  const merged: Omit<GraphemeCondition, "alias"> = {
    ...(aliasCondition ?? {}),
    ...explicitFields,
  };
  merged.syllableShape = mergeSyllableShape(aliasCondition?.syllableShape, explicitSyllableShape);
  if (!merged.syllableShape) delete merged.syllableShape;
  return merged;
}

function preExpandConditions(
  graphemes: Grapheme[],
  categories: Map<string, Set<string>>,
  aliases: LanguageConfig["graphemeConditionAliases"] | undefined,
): Map<Grapheme, PreExpandedCondition> {
  const result = new Map<Grapheme, PreExpandedCondition>();
  for (const g of graphemes) {
    const normalized = normalizeGraphemeCondition(g.condition, aliases, g.form);
    if (!normalized) continue;
    const expanded: PreExpandedCondition = {};
    if (normalized.leftContext) expanded.leftContext = expandContext(normalized.leftContext, categories);
    if (normalized.rightContext) expanded.rightContext = expandContext(normalized.rightContext, categories);
    if (normalized.notLeftContext) expanded.notLeftContext = expandContext(normalized.notLeftContext, categories);
    if (normalized.notRightContext) expanded.notRightContext = expandContext(normalized.notRightContext, categories);
    if (normalized.leftGraphemeContext) expanded.leftGraphemeContext = new Set(normalized.leftGraphemeContext);
    if (normalized.notLeftGraphemeContext) expanded.notLeftGraphemeContext = new Set(normalized.notLeftGraphemeContext);
    if (normalized.wordPosition) expanded.wordPosition = normalized.wordPosition;
    if (normalized.syllableShape) expanded.syllableShape = normalized.syllableShape;
    result.set(g, expanded);
  }
  return result;
}

function checkClusterShapeRequirement(length: number, requirement: "empty" | "nonEmpty" | "any" | undefined): boolean {
  if (!requirement || requirement === "any") return true;
  if (requirement === "empty") return length === 0;
  return length > 0;
}

function checkNucleusLengthRequirement(
  length: number,
  requirement: NonNullable<GraphemeCondition["syllableShape"]>["nucleusLength"],
): boolean {
  if (requirement === undefined) return true;
  if (typeof requirement === "number") return length === requirement;
  if (requirement.min !== undefined && length < requirement.min) return false;
  if (requirement.max !== undefined && length > requirement.max) return false;
  return true;
}

// ---------------------------------------------------------------------------
// Pipeline Step 1: Get candidates
// ---------------------------------------------------------------------------

function getGraphemeCandidates(
  graphemeMaps: LanguageConfig["graphemeMaps"],
  sound: string,
  position: "onset" | "nucleus" | "coda",
): Grapheme[] {
  return graphemeMaps[position].get(sound) ?? [];
}

// ---------------------------------------------------------------------------
// Pipeline Step 2: Filter by context condition
// ---------------------------------------------------------------------------

function meetsPreExpandedCondition(
  condition: PreExpandedCondition | undefined,
  prevPhoneme: Phoneme | undefined,
  nextPhoneme: Phoneme | undefined,
  isStartOfWord: boolean,
  isEndOfWord: boolean,
  totalPhonemes: number,
  phonemeIndex: number,
  prevGraphemeForm?: string,
  onsetLength?: number,
  nucleusLength?: number,
  codaLength?: number,
): boolean {
  if (!condition) return true;

  if (condition.wordPosition) {
    let positionMatch = false;
    const isInitial = isStartOfWord;
    const isFinal = isEndOfWord;
    const isMedial = !isInitial && !isFinal;

    for (const pos of condition.wordPosition) {
      if (pos === "initial" && isInitial) positionMatch = true;
      if (pos === "final" && isFinal) positionMatch = true;
      if (pos === "medial" && isMedial) positionMatch = true;
    }
    if (!positionMatch) return false;
  }

  if (condition.leftContext) {
    if (!prevPhoneme) return false;
    if (!condition.leftContext.has(prevPhoneme.sound)) return false;
  }

  if (condition.rightContext) {
    if (!nextPhoneme) return false;
    if (!condition.rightContext.has(nextPhoneme.sound)) return false;
  }

  if (condition.notLeftContext) {
    if (prevPhoneme && condition.notLeftContext.has(prevPhoneme.sound)) return false;
  }

  if (condition.notRightContext) {
    if (nextPhoneme && condition.notRightContext.has(nextPhoneme.sound)) return false;
  }

  if (condition.leftGraphemeContext) {
    if (!prevGraphemeForm) return false;
    const lastLetter = prevGraphemeForm[prevGraphemeForm.length - 1];
    if (!condition.leftGraphemeContext.has(lastLetter)) return false;
  }

  if (condition.notLeftGraphemeContext) {
    if (prevGraphemeForm) {
      const lastLetter = prevGraphemeForm[prevGraphemeForm.length - 1];
      if (condition.notLeftGraphemeContext.has(lastLetter)) return false;
    }
  }

  if (condition.syllableShape) {
    if (!checkClusterShapeRequirement(onsetLength ?? 0, condition.syllableShape.onset)) return false;
    if (!checkClusterShapeRequirement(codaLength ?? 0, condition.syllableShape.coda)) return false;
    if (!checkNucleusLengthRequirement(nucleusLength ?? 0, condition.syllableShape.nucleusLength)) return false;
  }

  return true;
}

function filterByCondition(
  candidates: Grapheme[],
  expandedConditions: Map<Grapheme, PreExpandedCondition>,
  prevPhoneme: Phoneme | undefined,
  nextPhoneme: Phoneme | undefined,
  phonemeIndex: number,
  totalPhonemes: number,
  isStartOfWord: boolean,
  isEndOfWord: boolean,
  prevGraphemeForm?: string,
  onsetLength?: number,
  nucleusLength?: number,
  codaLength?: number,
): Grapheme[] {
  const filtered = candidates.filter(g =>
    meetsPreExpandedCondition(
      expandedConditions.get(g),
      prevPhoneme,
      nextPhoneme,
      isStartOfWord,
      isEndOfWord,
      totalPhonemes,
      phonemeIndex,
      prevGraphemeForm,
      onsetLength,
      nucleusLength,
      codaLength,
    )
  );
  return filtered.length > 0 ? filtered : candidates;
}

// ---------------------------------------------------------------------------
// Pipeline Step 3: Filter by position
// ---------------------------------------------------------------------------

export function filterByPosition(
  candidates: Grapheme[],
  isCluster: boolean,
  isStartOfWord: boolean,
  isEndOfWord: boolean,
): Grapheme[] {
  const isMidWord = !isStartOfWord && !isEndOfWord;

  // Tier 1: strict — require positive values (undefined = pass)
  const strict = candidates.filter(g =>
    (!isCluster || g.cluster === undefined || g.cluster > 0) &&
    (!isStartOfWord || g.startWord === undefined || g.startWord > 0) &&
    (!isEndOfWord || g.endWord === undefined || g.endWord > 0) &&
    (!isMidWord || g.midWord === undefined || g.midWord > 0)
  );
  if (strict.length > 0) return strict;

  // Tier 2: relaxed — only exclude explicit bans (=== 0)
  const relaxed = candidates.filter(g =>
    (!isCluster || g.cluster !== 0) &&
    (!isStartOfWord || g.startWord !== 0) &&
    (!isEndOfWord || g.endWord !== 0) &&
    (!isMidWord || g.midWord !== 0)
  );
  if (relaxed.length > 0) return relaxed;

  // Tier 3: last resort (should never happen with well-configured graphemes)
  return candidates;
}

// ---------------------------------------------------------------------------
// Pipeline Step 4: Frequency-weighted random selection
// ---------------------------------------------------------------------------

interface FrequencyResult extends Grapheme {
  _weights?: [string, number][];
  _roll?: number;
}

function selectByFrequency(
  candidates: Grapheme[],
  rand: RNG,
  isStartOfWord: boolean,
  isEndOfWord: boolean,
  captureTrace: boolean = false,
  position?: "onset" | "nucleus" | "coda",
  stress?: string,
  syllableCount?: number,
): FrequencyResult {
  if (candidates.length === 0) return { phoneme: "", form: "", origin: 0, frequency: 0, startWord: 0, midWord: 0, endWord: 0 };
  if (candidates.length === 1) {
    const r: FrequencyResult = { ...candidates[0] };
    if (captureTrace) { r._weights = [[candidates[0].form, 1]]; r._roll = 0; }
    return r;
  }

  const weights: [Grapheme, number][] = [];
  const traceWeights: [string, number][] = [];
  for (const g of candidates) {
    // For monosyllables (both isStartOfWord AND isEndOfWord), use the maximum position weight
    // to avoid defaulting to startWord=0 for final phonemes (e.g. /dz/ → "dse")
    const posWeight = (isStartOfWord && isEndOfWord)
      ? Math.max(g.startWord ?? 1, g.endWord ?? 1, g.midWord ?? 1)
      : isStartOfWord
        ? (g.startWord ?? 1)
        : isEndOfWord
          ? (g.endWord ?? 1)
          : (g.midWord ?? 1);
    // In unstressed syllables of polysyllabic words, penalize multi-letter
    // vowel graphemes. CMU data shows vowel LPP drops from 1.58 (1-syl) to
    // 1.02 (5-syl) — unstressed vowels are almost always single letters.
    let stressModifier = 1;
    if (stress !== "ˈ" && syllableCount && syllableCount >= 2 && g.form.length > 1) {
      if (position === "nucleus") {
        stressModifier = Math.max(0.02, 0.15 / syllableCount);
      } else {
        stressModifier = Math.max(0.15, 0.5 / syllableCount);
      }
    }
    const w = g.frequency * posWeight * stressModifier;
    weights.push([g, w]);
    if (captureTrace) traceWeights.push([g.form, w]);
  }

  const totalWeight = weights.reduce((sum, [, weight]) => sum + weight, 0);
  const randomValue = rand() * totalWeight;

  let cumulativeWeight = 0;
  let selected = weights[weights.length - 1][0];
  for (const [option, weight] of weights) {
    cumulativeWeight += weight;
    if (randomValue < cumulativeWeight) {
      selected = option;
      break;
    }
  }

  const result: FrequencyResult = { ...selected };

  if (captureTrace) {
    result._weights = traceWeights;
    result._roll = randomValue;
  }

  return result;
}

// ---------------------------------------------------------------------------
// Pipeline Step 5: Doubling (factory pattern)
// ---------------------------------------------------------------------------

interface DoublingState {
  doublingCount: number;
}

interface DoublingTraceInfo {
  attempted: boolean;
  reason?: string;
  probability?: number;
  result?: string;
}

/** Per-phoneme context for the doubling decision. */
interface DoublingSlot {
  form: string;
  phoneme: Phoneme;
  position: "onset" | "nucleus" | "coda";
  prevPhoneme?: Phoneme;
  nextNucleus?: Phoneme;
  nucleusForm: string;
  stress?: string;
  prevReduced: boolean;
  isCluster: boolean;
  isFirstInCoda: boolean;
  isLastPhoneme: boolean;
  isEndOfWord: boolean;
  isMonosyllabic: boolean;
  nextIsConsonant: boolean;
}

type DoublingFn = (slot: DoublingSlot, state: DoublingState, rand: RNG, trace?: DoublingTraceInfo) => string;

/**
 * Create a doubling function bound to the given config.
 * Config-level invariants (probability, trigger, never-double list, doubled forms)
 * are captured once; only per-phoneme context is passed at call time.
 */
function createDoublingFn(
  config: DoublingConfig | undefined,
  neverDoubleSet: Set<string>,
  doubledFormSet: Set<string>,
): DoublingFn {
  if (!config?.enabled) {
    return (slot, _state, _rand, trace) => {
      if (trace) { trace.attempted = false; trace.reason = "disabled"; }
      return slot.form;
    };
  }

  const doubledFormLookup = config.doubledForms ?? {};

  return function applyDoubling(slot, state, rand, trace) {
    const {
      form, phoneme, position, prevPhoneme, nextNucleus, nucleusForm,
      stress, prevReduced, isCluster, isFirstInCoda,
      isLastPhoneme, isEndOfWord, isMonosyllabic, nextIsConsonant,
    } = slot;

    const skip = (reason: string) => {
      if (trace) { trace.attempted = false; trace.reason = reason; }
      return form;
    };

    if (!prevPhoneme) return skip("no-prev-phoneme");

    // Allow doubling for the first consonant in a coda cluster ONLY if it has a custom
    // doubledForm (e.g. k→ck in "backs"), not a simple letter repeat (p→pp).
    // Simple repeats before more coda consonants create impossible clusters: ppt, nnd, ddz, ggz.
    if (isCluster) {
      if (position === "coda" && isFirstInCoda && doubledFormLookup[form]) {
        // Custom doubled form like k→ck is fine in clusters (e.g. "cks")
      } else {
        return skip("in-cluster");
      }
    }

    // Suppress doubling when a coda consonant is followed by another consonant (onset of next syllable).
    // Doubling here creates impossible cross-syllable clusters: "nn" + "t" → "nnt", "ll" + "d" → "lld".
    if (position === "coda" && nextIsConsonant) return skip("coda-before-consonant");

    if (form.length !== 1) {
      // "ck" etc. selected directly from grapheme map — still counts toward maxPerWord
      if (doubledFormSet.has(form)) {
        state.doublingCount++;
      }
      return skip("multi-char-grapheme");
    }
    if (position !== "onset" && position !== "coda") return skip("nucleus-position");
    if (state.doublingCount >= config.maxPerWord) return skip("max-per-word");

    // Phonological trigger
    if (config.trigger === "lax-vowel") {
      const isAfterVowel = prevPhoneme.nucleus != null && prevPhoneme.nucleus > 0;
      const isLax = prevPhoneme.tense === false;
      if (!isAfterVowel || !isLax) return skip("trigger:not-after-lax-vowel");
    }

    // Doubling signals "short vowel" to the reader — but only works when the
    // nucleus *looks like* a vowel on the page. Vowel graphemes that end in a
    // consonant letter (e.g. /ɚ/ → "er"/"or"/"ur") break the visual signal:
    // "erss" reads as a consonant pileup, not doubled-after-short-vowel.
    // Empty on first-syllable onset (no preceding nucleus) — the lax-vowel
    // trigger above already rejects that case.
    if (nucleusForm.length > 0) {
      const lastNucleusChar = nucleusForm[nucleusForm.length - 1].toLowerCase();
      if (!VOWEL_LETTERS.has(lastNucleusChar)) return skip("nucleus-ends-consonant-letter");
    }

    // neverDoubleFinal — suppress word-final doubling for specific sounds
    if (isEndOfWord && isLastPhoneme && config.neverDoubleFinal?.includes(phoneme.sound)) return skip("never-double-final");

    // neverDouble — check both phoneme sound and grapheme form
    if (neverDoubleSet.has(phoneme.sound)) return skip("never-double:sound");
    if (neverDoubleSet.has(form)) return skip("never-double:form");

    // finalDoublingOnly
    if (isEndOfWord && config.finalDoublingOnly && config.finalDoublingOnly.length > 0) {
      if (!config.finalDoublingOnly.includes(phoneme.sound)) return skip("final-doubling-only");
    }

    // suppressAfterReduction
    if (config.suppressAfterReduction && prevReduced) return skip("suppress-after-reduction");

    // suppressBeforeTense
    if (config.suppressBeforeTense && nextNucleus) {
      if (nextNucleus.tense === true) return skip("suppress-before-tense");
    }

    // Calculate probability
    let prob = config.probability;
    // Monosyllables are inherently stressed even without a ˈ marker.
    // Only apply unstressed modifier to genuinely unstressed syllables in polysyllabic words.
    if (config.unstressedModifier != null && !stress && !isMonosyllabic) {
      prob *= config.unstressedModifier;
    }
    prob = Math.min(100, Math.max(0, Math.round(prob)));
    if (prob <= 0) return skip("zero-probability:unstressed");

    const shouldDouble = rand() * 100 < prob;
    if (shouldDouble) {
      state.doublingCount++;
      const doubled = doubledFormLookup[form] ?? (form + form);
      if (trace) { trace.attempted = true; trace.probability = prob; trace.result = doubled; }
      return doubled;
    }
    if (trace) { trace.attempted = true; trace.probability = prob; trace.reason = "roll-failed"; }
    return form;
  };
}

// ---------------------------------------------------------------------------
// Consonant pileup repair (grapheme-aware)
// ---------------------------------------------------------------------------

/** Default English consonant graphemes (longest first for greedy matching). */
const DEFAULT_CONSONANT_GRAPHEMES = ["tch", "dge", "ch", "sh", "th", "ng", "ph", "wh", "ck"];

/**
 * Tokenize a string into grapheme units using longest-match-first.
 * Multi-letter consonant graphemes (e.g. "tch", "ch", "sh") are treated as
 * atomic units. Remaining characters become single-letter tokens.
 *
 * @example tokenizeGraphemes("tchwng") → ["tch", "w", "ng"]
 * @example tokenizeGraphemes("strengths") → ["s", "t", "r", "e", "ng", "th", "s"]
 */
export function tokenizeGraphemes(str: string, graphemeList: string[] = DEFAULT_CONSONANT_GRAPHEMES): string[] {
  const tokens: string[] = [];
  let i = 0;
  while (i < str.length) {
    let matched = false;
    // Try longest graphemes first (list is pre-sorted longest first)
    for (const g of graphemeList) {
      if (str.startsWith(g, i)) {
        tokens.push(g);
        i += g.length;
        matched = true;
        break;
      }
    }
    if (!matched) {
      tokens.push(str[i]);
      i++;
    }
  }
  return tokens;
}

/** Check if a grapheme token is a consonant (contains no vowel letters). */
function isConsonantToken(token: string, tokenIdx?: number, allTokens?: string[]): boolean {
  const fullStr = allTokens ? allTokens.join("") : token;
  // Compute char offset of this token within the full string
  let charOffset = 0;
  if (allTokens && tokenIdx !== undefined) {
    for (let t = 0; t < tokenIdx; t++) charOffset += allTokens[t].length;
  }
  for (let i = 0; i < token.length; i++) {
    if (isVowelChar(token[i], charOffset + i, fullStr)) return false;
  }
  return true;
}

/**
 * Repair consonant pileups by capping consecutive consonant grapheme units at `max`.
 * Mutates `cleanParts` and `hyphenatedParts` in place.
 *
 * Strategy: when a consonant run exceeds `max` grapheme units, find the
 * syllable boundary within the run, determine which side (coda vs onset)
 * contributes more, and drop entire grapheme tokens from the heavier side
 * (interior-first) until the run fits.
 */
export function repairConsonantPileups(
  cleanParts: string[],
  hyphenatedParts: string[],
  maxConsonantGraphemes: number,
  consonantGraphemes?: string[],
): void {
  const gList = consonantGraphemes ?? DEFAULT_CONSONANT_GRAPHEMES;

  for (let pass = 0; pass < 10; pass++) {
    const word = cleanParts.join("");
    const tokens = tokenizeGraphemes(word, gList);

    // Find first consonant run exceeding max (in tokens)
    let runStart = -1;
    let runLen = 0;
    let found = false;
    let foundRunStart = -1;
    let foundRunLen = 0;

    for (let i = 0; i <= tokens.length; i++) {
      if (i < tokens.length && isConsonantToken(tokens[i])) {
        if (runStart < 0) runStart = i;
        runLen = i - runStart + 1;
      } else {
        if (runLen > maxConsonantGraphemes) {
          found = true;
          foundRunStart = runStart;
          foundRunLen = runLen;
          break;
        }
        runStart = -1;
        runLen = 0;
      }
    }

    if (!found) return;

    // Convert token indices to character positions
    const tokenCharStarts: number[] = [];
    let charPos = 0;
    for (const t of tokens) {
      tokenCharStarts.push(charPos);
      charPos += t.length;
    }

    const runCharStart = tokenCharStarts[foundRunStart];
    const runCharEnd = foundRunStart + foundRunLen < tokens.length
      ? tokenCharStarts[foundRunStart + foundRunLen]
      : word.length;

    // Map character positions to parts
    const cumLengths: number[] = [];
    let cum = 0;
    for (const part of cleanParts) {
      cum += part.length;
      cumLengths.push(cum);
    }

    function partIndexOf(charIdx: number): number {
      for (let p = 0; p < cumLengths.length; p++) {
        if (charIdx < cumLengths[p]) return p;
      }
      return cumLengths.length - 1;
    }

    const startPart = partIndexOf(runCharStart);
    const endPart = partIndexOf(runCharEnd - 1);
    const excess = foundRunLen - maxConsonantGraphemes;

    if (startPart === endPart) {
      // Run within a single syllable — drop interior tokens
      const partCharStart = startPart > 0 ? cumLengths[startPart - 1] : 0;
      const runTokens = tokens.slice(foundRunStart, foundRunStart + foundRunLen);

      // Remove interior tokens (not first/last), middle-outward
      const interior = runTokens.slice(1, -1);
      const midIdx = Math.floor(interior.length / 2);
      const removeOrder: number[] = [];
      for (let d = 0; d <= interior.length; d++) {
        if (midIdx + d < interior.length) removeOrder.push(midIdx + d);
        if (d > 0 && midIdx - d >= 0) removeOrder.push(midIdx - d);
      }

      const toRemoveSet = new Set<number>();
      for (const idx of removeOrder) {
        if (toRemoveSet.size >= excess) break;
        toRemoveSet.add(idx);
      }

      const kept = [runTokens[0]];
      for (let i = 0; i < interior.length; i++) {
        if (!toRemoveSet.has(i)) kept.push(interior[i]);
      }
      kept.push(runTokens[runTokens.length - 1]);

      const localStart = runCharStart - partCharStart;
      const localEnd = runCharEnd - partCharStart;
      const part = cleanParts[startPart];
      cleanParts[startPart] = part.slice(0, localStart) + kept.join("") + part.slice(localEnd);
      hyphenatedParts[startPart * 2] = cleanParts[startPart];
      continue;
    }

    // Run spans boundary — count coda vs onset tokens
    const boundaryCharIdx = cumLengths[startPart];
    // Count tokens belonging to coda (chars < boundaryCharIdx)
    let codaTokenCount = 0;
    for (let ti = foundRunStart; ti < foundRunStart + foundRunLen; ti++) {
      if (tokenCharStarts[ti] < boundaryCharIdx) codaTokenCount++;
      else break;
    }
    const onsetTokenCount = foundRunLen - codaTokenCount;

    // Drop from heavier side; tie → coda
    const dropFromCoda = codaTokenCount >= onsetTokenCount;
    const targetPartIdx = dropFromCoda ? startPart : endPart;
    const part = cleanParts[targetPartIdx];

    // Tokenize just this part
    const partTokens = tokenizeGraphemes(part, gList);

    // Find the consonant tokens at the relevant edge
    const edgeTokens: { tokenIdx: number; token: string }[] = [];
    if (dropFromCoda) {
      // Consonant tokens at end of part
      for (let i = partTokens.length - 1; i >= 0 && isConsonantToken(partTokens[i]); i--) {
        edgeTokens.unshift({ tokenIdx: i, token: partTokens[i] });
      }
    } else {
      // Consonant tokens at start of part
      for (let i = 0; i < partTokens.length && isConsonantToken(partTokens[i]); i++) {
        edgeTokens.push({ tokenIdx: i, token: partTokens[i] });
      }
    }

    // Remove interior tokens first, then edges
    const toRemoveIndices = new Set<number>();
    if (edgeTokens.length > 2) {
      const interior = edgeTokens.slice(1, -1);
      const mid = Math.floor(interior.length / 2);
      const order: typeof interior = [];
      for (let d = 0; d <= interior.length; d++) {
        if (mid + d < interior.length) order.push(interior[mid + d]);
        if (d > 0 && mid - d >= 0) order.push(interior[mid - d]);
      }
      for (const e of order) {
        if (toRemoveIndices.size >= excess) break;
        toRemoveIndices.add(e.tokenIdx);
      }
    }
    // If still need more, remove from edges
    if (toRemoveIndices.size < excess) {
      const candidates = dropFromCoda ? edgeTokens : [...edgeTokens].reverse();
      for (const e of candidates) {
        if (toRemoveIndices.size >= excess) break;
        if (!toRemoveIndices.has(e.tokenIdx)) toRemoveIndices.add(e.tokenIdx);
      }
    }

    const newPart = partTokens.filter((_, i) => !toRemoveIndices.has(i)).join("");
    cleanParts[targetPartIdx] = newPart;
    hyphenatedParts[targetPartIdx * 2] = newPart;
  }
}

// ---------------------------------------------------------------------------
// Articulatory helpers for feature-based junction validation
// ---------------------------------------------------------------------------

export function mannerGroup(p: Phoneme): string {
  const m = p.mannerOfArticulation;
  if (m === "sibilant") return "fricative";
  if (m === "lateralApproximant") return "liquid";
  return m;
}

export function isCoronal(p: Phoneme): boolean {
  const place = p.placeOfArticulation;
  return place === "alveolar" || place === "postalveolar" || place === "dental";
}

export function placeGroup(p: Phoneme): string {
  const place = p.placeOfArticulation;
  if (place === "bilabial" || place === "labiodental" || place === "labial-velar") return "labial";
  if (place === "dental" || place === "alveolar" || place === "postalveolar") return "coronal";
  if (place === "palatal" || place === "velar") return "dorsal";
  return place; // glottal etc.
}

// ---------------------------------------------------------------------------
// Syllable boundary type for junction validation
// ---------------------------------------------------------------------------

export interface SyllableBoundary {
  codaCluster: Phoneme[];
  onsetCluster: Phoneme[];
}

// ---------------------------------------------------------------------------
// Feature-based junction validation
// ---------------------------------------------------------------------------

/**
 * Repair coda→onset junctions using feature-based articulatory rules.
 * Drops grapheme tokens from the coda side when the junction is invalid.
 * Mutates `cleanParts` and `hyphenatedParts` in place.
 *
 * @backstop Since Phase A (#250) moved full-cluster SSP validation into
 * `adjustBoundary` (generate.ts), this function no longer fires in practice
 * — measured at 0 repairs across 50k words (2026-02-21). Retained as a
 * safety net in case upstream generation changes reintroduce invalid
 * junctions. If this fires, it likely indicates a regression in the
 * generation pipeline.
 */
export function repairJunctions(
  cleanParts: string[],
  hyphenatedParts: string[],
  boundaries: SyllableBoundary[],
  config: LanguageConfig,
  consonantGraphemes?: string[],
): void {
  const gList = consonantGraphemes ?? DEFAULT_CONSONANT_GRAPHEMES;

  for (let pass = 0; pass < 10; pass++) {
    let changed = false;
    for (let i = 0; i < boundaries.length; i++) {
      const { onsetCluster, codaCluster } = boundaries[i];
      if (codaCluster.length === 0 || onsetCluster.length === 0) continue;

      if (!validateJunction(codaCluster, onsetCluster, config)) {
        // Drop the last consonant grapheme token from the coda part
        const codaPart = cleanParts[i];
        if (!codaPart) continue;

        const codaTokens = tokenizeGraphemes(codaPart, gList);
        let lastCodaConsonantIdx = -1;
        for (let j = codaTokens.length - 1; j >= 0; j--) {
          if (isConsonantToken(codaTokens[j])) { lastCodaConsonantIdx = j; break; }
        }
        if (lastCodaConsonantIdx < 0) continue;

        // Save the dropped token, then splice it out
        const droppedToken = codaTokens[lastCodaConsonantIdx];
        codaTokens.splice(lastCodaConsonantIdx, 1);

        // If the new last consonant is identical (doubled), drop it too
        const newLastIdx = codaTokens.length > 0
          ? codaTokens.reduce((last, t, j) => isConsonantToken(t) ? j : last, -1)
          : -1;
        if (newLastIdx >= 0 && codaTokens[newLastIdx] === droppedToken) {
          codaTokens.splice(newLastIdx, 1);
        }

        cleanParts[i] = codaTokens.join("");
        hyphenatedParts[i * 2] = cleanParts[i];

        // Update coda phonemes for next pass (cascading repair)
        if (boundaries[i].codaCluster.length > 0) {
          boundaries[i].codaCluster.pop();
        }
        changed = true;
      }
    }
    if (!changed) return;
  }
}

// ---------------------------------------------------------------------------
// Raw consonant letter repair (backstop)
// ---------------------------------------------------------------------------

/**
 * Repair consonant pileups by counting raw consonant *letters* (not grapheme units).
 * Mutates `cleanParts` and `hyphenatedParts` in place.
 */
export function repairConsonantLetters(
  cleanParts: string[],
  hyphenatedParts: string[],
  maxLetters: number,
): void {
  for (let pass = 0; pass < 10; pass++) {
    const word = cleanParts.join("");

    // Find first run of consonant letters exceeding max
    let runStart = -1;
    let runLen = 0;
    let found = false;
    let foundStart = -1;
    let foundLen = 0;

    for (let i = 0; i <= word.length; i++) {
      if (i < word.length && isConsonantLetter(word[i], i, word)) {
        if (runStart < 0) runStart = i;
        runLen = i - runStart + 1;
      } else {
        if (runLen > maxLetters) {
          found = true;
          foundStart = runStart;
          foundLen = runLen;
          break;
        }
        runStart = -1;
        runLen = 0;
      }
    }

    if (!found) return;

    // Map char positions to parts
    const cumLengths: number[] = [];
    let cum = 0;
    for (const part of cleanParts) {
      cum += part.length;
      cumLengths.push(cum);
    }

    function partIndexOf(charIdx: number): number {
      for (let p = 0; p < cumLengths.length; p++) {
        if (charIdx < cumLengths[p]) return p;
      }
      return cumLengths.length - 1;
    }

    const startPart = partIndexOf(foundStart);
    const endPart = partIndexOf(foundStart + foundLen - 1);

    // Drop from the heavier side at the boundary
    const boundaryCharIdx = startPart < endPart ? cumLengths[startPart] : -1;

    let dropPartIdx: number;
    if (boundaryCharIdx < 0) {
      dropPartIdx = startPart;
    } else {
      const codaCount = boundaryCharIdx - foundStart;
      const onsetCount = foundLen - codaCount;
      dropPartIdx = codaCount >= onsetCount ? startPart : endPart;
    }

    const part = cleanParts[dropPartIdx];
    const partStart = dropPartIdx > 0 ? cumLengths[dropPartIdx - 1] : 0;

    // Find consonant letters in this part that are within the run
    const consonantIndices: number[] = [];
    for (let ci = 0; ci < part.length; ci++) {
      const globalIdx = partStart + ci;
      if (globalIdx >= foundStart && globalIdx < foundStart + foundLen && isConsonantLetter(part[ci], globalIdx, word)) {
        consonantIndices.push(ci);
      }
    }

    if (consonantIndices.length <= 1) return; // can't drop

    // Drop interior consonant (middle-outward)
    const interior = consonantIndices.slice(1, -1);
    const dropIdx = interior.length > 0
      ? interior[Math.floor(interior.length / 2)]
      : consonantIndices[Math.floor(consonantIndices.length / 2)];

    cleanParts[dropPartIdx] = part.slice(0, dropIdx) + part.slice(dropIdx + 1);
    hyphenatedParts[dropPartIdx * 2] = cleanParts[dropPartIdx];
  }
}

/**
 * Repair vowel pileups by counting raw vowel *letters* (a, e, i, o, u, y).
 * Trims excess vowels from the end of any run exceeding `maxLetters`.
 * Mutates `cleanParts` and `hyphenatedParts` in place.
 */
export function repairVowelLetters(
  cleanParts: string[],
  hyphenatedParts: string[],
  maxLetters: number,
): void {
  for (let i = 0; i < cleanParts.length; i++) {
    const part = cleanParts[i];
    let result = "";
    let vowelRun = 0;
    for (let j = 0; j < part.length; j++) {
      if (isVowelChar(part[j], j, part)) {
        vowelRun++;
        if (vowelRun <= maxLetters) result += part[j];
      } else {
        vowelRun = 0;
        result += part[j];
      }
    }
    if (result !== part) {
      cleanParts[i] = result;
      hyphenatedParts[i * 2] = result;
    }
  }
}

// ---------------------------------------------------------------------------
// Word-final consonant letter repair
// ---------------------------------------------------------------------------

/**
 * Trim word-final consonant letter runs that exceed `maxLetters`.
 * Drops interior consonant letters from the last part's trailing cluster.
 */
export function repairFinalConsonantLetters(
  cleanParts: string[],
  hyphenatedParts: string[],
  maxLetters: number,
): void {
  if (cleanParts.length === 0) return;

  const word = cleanParts.join("");
  // Find trailing consonant run
  let runLen = 0;
  for (let i = word.length - 1; i >= 0; i--) {
    if (isConsonantLetter(word[i], i, word)) runLen++;
    else break;
  }

  if (runLen <= maxLetters) return;

  // Work on the last part
  const lastIdx = cleanParts.length - 1;
  let part = cleanParts[lastIdx];

  // Find trailing consonant letters in this part
  let partRunLen = 0;
  for (let i = part.length - 1; i >= 0; i--) {
    if (isConsonantLetter(part[i], i, part)) partRunLen++;
    else break;
  }

  if (partRunLen <= maxLetters) {
    // The run spans parts — just trim from the last part
    // This is rare; keep what we have
    return;
  }

  // Drop interior consonants from the trailing cluster to fit maxLetters
  const clusterStart = part.length - partRunLen;
  const cluster = part.slice(clusterStart);

  // Keep first and last letters, drop from interior
  if (cluster.length <= maxLetters) return;

  // Keep the last `maxLetters` letters (preserves word-final sounds)
  const trimmed = cluster.slice(cluster.length - maxLetters);
  part = part.slice(0, clusterStart) + trimmed;

  cleanParts[lastIdx] = part;
  hyphenatedParts[lastIdx * 2] = part;
}

// ---------------------------------------------------------------------------
// Silent-e (magic-e / split digraph)
// ---------------------------------------------------------------------------

/** Pre-compiled silent-e swap lookup: phoneme → [{from, to}] sorted longest-from-first. */
type SilentELookup = Map<string, { from: string; to: string }[]>;

function buildSilentELookup(config: SilentEConfig): SilentELookup {
  const map = new Map<string, { from: string; to: string }[]>();
  for (const swap of config.swaps) {
    let list = map.get(swap.phoneme);
    if (!list) { list = []; map.set(swap.phoneme, list); }
    list.push({ from: swap.from, to: swap.to });
  }
  // Sort each list longest-from-first for greedy matching
  for (const list of map.values()) {
    list.sort((a, b) => b.from.length - a.from.length);
  }
  return map;
}

/**
 * Attempt to apply silent-e to the final syllable of a word.
 *
 * Requirements:
 * - Final syllable has exactly 1 coda consonant
 * - That consonant is not in the excluded set
 * - The nucleus phoneme has a matching swap
 * - The written nucleus grapheme matches the swap's `from`
 *
 * Returns the modified cleanParts/hyphenatedParts (mutated in place) or leaves unchanged.
 */
export function applySilentE(
  cleanParts: string[],
  hyphenatedParts: string[],
  syllables: { onset: Phoneme[]; nucleus: Phoneme[]; coda: Phoneme[] }[],
  nucleusGraphemes: string[],
  lookup: SilentELookup,
  excludedCodas: Set<string>,
  probability: number,
  rand: RNG,
): void {
  if (syllables.length === 0 || cleanParts.length === 0) return;

  const lastSylIdx = syllables.length - 1;
  const lastSyl = syllables[lastSylIdx];

  // Must have 1-2 coda consonants (silent-e works with clusters like "nce", "nge", "rse")
  if (lastSyl.coda.length < 1 || lastSyl.coda.length > 2) return;

  // Must have a nucleus
  if (lastSyl.nucleus.length !== 1) return;

  // Check excluded coda sounds (check last coda consonant — the one before "e")
  const codaSound = lastSyl.coda[lastSyl.coda.length - 1].sound;
  if (excludedCodas.has(codaSound)) return;

  // Check if nucleus phoneme has eligible swaps
  const nucleusSound = lastSyl.nucleus[0].sound;
  const swaps = lookup.get(nucleusSound);
  if (!swaps) return;

  // Get the nucleus grapheme that was selected for this syllable
  const nucleusForm = nucleusGraphemes[lastSylIdx];
  if (!nucleusForm) return;

  // Find a matching swap
  const swap = swaps.find(s => s.from === nucleusForm);
  if (!swap) return;

  // Probability check — monosyllables get a higher rate (English monosyllables
  // have ~16.6% silent-e vs ~8-10% for polysyllabic words)
  const effectiveProb = syllables.length === 1 ? Math.min(100, probability * 2.0) : probability;
  if (rand() >= effectiveProb / 100) return;

  // Apply the swap: replace the vowel grapheme in the last clean part and append 'e'
  const lastPartIdx = cleanParts.length - 1;
  const part = cleanParts[lastPartIdx];

  // Find the vowel grapheme in the written part.
  // The nucleus grapheme should appear before the final consonant grapheme(s).
  const fromIdx = part.lastIndexOf(swap.from);
  if (fromIdx < 0) return;

  // Ensure the swap target is in the vowel portion (before the final consonant letters)
  const newPart = part.slice(0, fromIdx) + swap.to + part.slice(fromIdx + swap.from.length) + "e";
  cleanParts[lastPartIdx] = newPart;
  hyphenatedParts[lastPartIdx * 2] = newPart;
}

// ---------------------------------------------------------------------------
// Silent-e: orthographic append (short-vowel contexts)
// ---------------------------------------------------------------------------

/** Pre-compiled lookup: IPA sound → probability */
type AppendAfterLookup = Map<string, number>;

function buildAppendAfterLookup(rules: SilentEAppendRule[]): AppendAfterLookup {
  return new Map(rules.map(r => [r.sound, r.probability]));
}

/**
 * Append silent-e after word-final consonants that orthographically require it
 * (e.g. English words never end in bare 'v'). Unlike magic-e, the vowel
 * grapheme is NOT changed — this is purely an orthographic append.
 *
 * Only applies when the magic-e swap did NOT already fire (to avoid double-e).
 */
export function appendSilentE(
  cleanParts: string[],
  hyphenatedParts: string[],
  syllables: { onset: Phoneme[]; nucleus: Phoneme[]; coda: Phoneme[] }[],
  appendLookup: AppendAfterLookup,
  rand: RNG,
): void {
  if (syllables.length === 0 || cleanParts.length === 0) return;

  const lastSyl = syllables[syllables.length - 1];
  if (lastSyl.coda.length === 0) return;

  // Check the final coda sound
  const finalCodaSound = lastSyl.coda[lastSyl.coda.length - 1].sound;
  const probability = appendLookup.get(finalCodaSound);
  if (probability === undefined) return;

  // Don't append if word already ends in 'e' (magic-e already applied)
  const lastPartIdx = cleanParts.length - 1;
  const part = cleanParts[lastPartIdx];
  if (part.length === 0 || part[part.length - 1] === "e") return;

  // Probability check
  if (rand() >= probability / 100) return;

  cleanParts[lastPartIdx] = part + "e";
  hyphenatedParts[lastPartIdx * 2] = cleanParts[lastPartIdx];
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

/**
 * Creates a `generateWrittenForm` function bound to the given language config's
 * grapheme maps. The cumulative frequency table is pre-computed once at creation.
 */
export function createWrittenFormGenerator(config: LanguageConfig): (context: WordGenerationContext) => void {
  const gMaps = config.graphemeMaps;
  const doublingConfig = config.doubling;
  const allCompiledRules = compileSpellingRules(config.spellingRules ?? []);
  const syllableRules = allCompiledRules.filter(r => r.scope === "syllable" || r.scope === "both");
  const wordRules = allCompiledRules.filter(r => r.scope === "word" || r.scope === "both");
  const categories = buildCategorySets(config.phonemes);
  const neverDoubleSet = new Set<string>(doublingConfig?.neverDouble ?? []);
  const doubledFormSet = new Set(Object.values(doublingConfig?.doubledForms ?? {}));
  const tryDoubling = createDoublingFn(doublingConfig, neverDoubleSet, doubledFormSet);

  // Pre-expand conditions for all graphemes
  const expandedConditions = preExpandConditions(config.graphemes, categories, config.graphemeConditionAliases);

  // Silent-e pre-compilation
  const silentEConfig = config.silentE;
  const silentELookup = silentEConfig?.enabled ? buildSilentELookup(silentEConfig) : undefined;
  const silentEExcluded = new Set<string>(silentEConfig?.excludedCodas ?? []);
  const appendAfterLookup = silentEConfig?.enabled && silentEConfig.appendAfter?.length
    ? buildAppendAfterLookup(silentEConfig.appendAfter)
    : undefined;

  return (context: WordGenerationContext) => {
    const rand = context.rand;
    const { syllables, written } = context.word;
    const tracing = !!context.trace;
    const traceUnits: TraceUnitSeed[] = [];
    let preRepairSurface = "";
    let preRepairOwners: number[] = [];
    const flattenedPhonemes = syllables.flatMap((syllable, syllableIndex) =>
      (["onset", "nucleus", "coda"] as const).flatMap((position) =>
        syllable[position].map((phoneme, positionIndex) => ({
          phoneme,
          syllableIndex,
          position,
          positionIndex,
          stress: syllable.stress,
        }))
      )
    );

    const cleanParts: string[] = [];
    const hyphenatedParts: string[] = [];
    let currentSyllable: string[] = [];
    let currentSyllableOwners: number[] = [];
    const doublingCtx: DoublingState = { doublingCount: 0 };
    const nucleusGraphemes: string[] = []; // Track nucleus grapheme form per syllable
    let currentNucleusForm = "";
    let prevNucleusForm = "";
    let prevGraphemeForm: string | undefined;

    for (let phonemeIndex = 0; phonemeIndex < flattenedPhonemes.length; phonemeIndex++) {
      const { phoneme, syllableIndex, position, positionIndex, stress } = flattenedPhonemes[phonemeIndex];
      const prevEntry = flattenedPhonemes[phonemeIndex - 1];
      const nextEntry = flattenedPhonemes[phonemeIndex + 1];

      const isCluster =
        (prevEntry?.syllableIndex === syllableIndex && prevEntry?.position === position) ||
        (nextEntry?.syllableIndex === syllableIndex && nextEntry?.position === position);

      const prevPhoneme = prevEntry?.phoneme;
      const prevReduced = prevPhoneme?.reduced ?? false;

      let nextNucleus: Phoneme | undefined;
      for (let j = phonemeIndex + 1; j < flattenedPhonemes.length; j++) {
        if (flattenedPhonemes[j].position === "nucleus") {
          nextNucleus = flattenedPhonemes[j].phoneme;
          break;
        }
      }

      const isStartOfWord = syllableIndex === 0;
      const isEndOfWord = syllableIndex === syllables.length - 1;
      const onsetLength = syllables[syllableIndex].onset.length;
      const nucleusLength = syllables[syllableIndex].nucleus.length;
      const codaLength = syllables[syllableIndex].coda.length;

      // Pipeline
      const isLastPhoneme = phonemeIndex === flattenedPhonemes.length - 1;
      const candidates = getGraphemeCandidates(gMaps, phoneme.sound, position);
      const conditioned = filterByCondition(
        candidates,
        expandedConditions,
        prevPhoneme,
        nextEntry?.phoneme,
        phonemeIndex,
        flattenedPhonemes.length,
        isStartOfWord,
        isEndOfWord,
        prevGraphemeForm,
        onsetLength,
        nucleusLength,
        codaLength,
      );
      const positional = filterByPosition(conditioned, isCluster, isStartOfWord, isEndOfWord);
      // When doubling quota is full, exclude doubled-form graphemes (e.g. "ck") so we don't exceed maxPerWord
      const quotaFiltered = doubledFormSet.size > 0 && doublingCtx.doublingCount >= (doublingConfig?.maxPerWord ?? Infinity)
        ? positional.filter(g => !doubledFormSet.has(g.form))
        : positional;
      const selected = selectByFrequency(quotaFiltered.length > 0 ? quotaFiltered : positional, rand, isStartOfWord, isEndOfWord, tracing, position, stress, syllables.length);
      if (position === "nucleus") currentNucleusForm = selected.form;
      const doublingTraceInfo: DoublingTraceInfo | undefined = context.trace ? { attempted: false } : undefined;
      // For doubling, use the nucleus grapheme that the reader sees before the
      // doubled consonant: for coda, that's the current syllable's nucleus; for
      // onset, it's the previous syllable's (the vowel the doubling "closes").
      const form = tryDoubling({
        form: selected.form,
        phoneme,
        position,
        prevPhoneme,
        nextNucleus,
        nucleusForm: position === "onset" ? prevNucleusForm : currentNucleusForm,
        stress,
        prevReduced,
        isCluster,
        isFirstInCoda: position === "coda" && prevEntry?.position !== "coda",
        isLastPhoneme,
        isEndOfWord,
        isMonosyllabic: syllables.length === 1,
        nextIsConsonant: nextEntry?.position === "onset" || (nextEntry?.syllableIndex === syllableIndex && nextEntry?.position === "coda"),
      }, doublingCtx, rand, doublingTraceInfo);
      prevGraphemeForm = form;

      let emitted = form;
      if (currentSyllable.length > 0 && form.length > 0 &&
          currentSyllable[currentSyllable.length - 1].slice(-1) === form[0]) {
        emitted = form.slice(1);
      }

      if (context.trace) {
        context.trace.recordGraphemeSelection({
          index: phonemeIndex,
          phoneme: phoneme.sound,
          position,
          syllableIndex,
          candidates: candidates.map(g => g.form),
          afterCondition: conditioned.map(g => g.form),
          afterPosition: positional.map(g => g.form),
          weights: selected._weights ?? [],
          roll: selected._roll ?? 0,
          selected: selected.form,
          emitted,
          doubled: form !== selected.form,
          doubling: doublingTraceInfo ? {
            attempted: doublingTraceInfo.attempted,
            reason: doublingTraceInfo.reason,
            probability: doublingTraceInfo.probability,
            result: doublingTraceInfo.result,
          } : undefined,
        });
      }
      currentSyllable.push(emitted);
      if (tracing && emitted.length > 0) {
        for (let ci = 0; ci < emitted.length; ci++) {
          currentSyllableOwners.push(phonemeIndex);
        }
      }
      if (tracing) {
        traceUnits.push({
          id: phonemeIndex,
          graphemeSelectionIndex: phonemeIndex,
          phoneme: phoneme.sound,
          position,
          positionIndex,
          syllableIndex,
          selected: selected.form,
          emitted,
        });
      }

      if (!nextEntry || nextEntry.syllableIndex !== syllableIndex) {
        const rawSyllable = currentSyllable.join("");
        let syllableStr = applySpellingRules(rawSyllable, syllableRules, rand, context.trace, `syllable:${syllableIndex}`);
        let syllableOwners = tracing
          ? remapOwnersThroughRewrite(rawSyllable, currentSyllableOwners, syllableStr)
          : [];

        if (cleanParts.length > 0 && syllableStr.length > 0 &&
            cleanParts[cleanParts.length - 1].slice(-1) === syllableStr[0]) {
          syllableStr = syllableStr.slice(1);
          if (tracing) syllableOwners = syllableOwners.slice(1);
        }

        cleanParts.push(syllableStr);
        hyphenatedParts.push(syllableStr);
        nucleusGraphemes.push(currentNucleusForm);
        if (tracing) {
          preRepairSurface += syllableStr;
          preRepairOwners.push(...syllableOwners);
        }

        if (nextEntry) {
          hyphenatedParts.push("&shy;");
        }

        currentSyllable = [];
        prevNucleusForm = currentNucleusForm;
        currentSyllableOwners = [];
        currentNucleusForm = "";
      }
    }

    if (tracing) {
      const cleanSurface = cleanParts.join("");
      if (preRepairSurface !== cleanSurface) {
        preRepairOwners = remapOwnersThroughRewrite(preRepairSurface, preRepairOwners, cleanSurface);
        preRepairSurface = cleanSurface;
      }
    }

    // Silent-e: rewrite final VCe patterns (magic-e for long vowels)
    if (silentELookup && silentEConfig) {
      applySilentE(
        cleanParts, hyphenatedParts, syllables, nucleusGraphemes,
        silentELookup, silentEExcluded, silentEConfig.probability, rand,
      );
    }

    // Silent-e: orthographic append for consonants that can't end bare (e.g. 'v')
    if (appendAfterLookup) {
      appendSilentE(cleanParts, hyphenatedParts, syllables, appendAfterLookup, rand);
    }

    // Orthographic repairs: configurable boundary-based insertion rules
    // (e.g. insert silent 'u' after 'g' before e/i/y to preserve hard-g).
    const orthoRepairs = config.writtenFormConstraints?.orthographicRepairs;
    if (orthoRepairs) {
      for (let si = 0; si < cleanParts.length - 1; si++) {
        const part = cleanParts[si];
        const nextPart = cleanParts[si + 1];
        if (part.length === 0 || nextPart.length === 0) continue;
        const junction = part[part.length - 1] + nextPart[0];
        for (const repair of orthoRepairs) {
          if (repair.boundaryMatch.test(junction)) {
            cleanParts[si] = part + repair.insert;
            hyphenatedParts[si * 2] = hyphenatedParts[si * 2] + repair.insert;
            break;
          }
        }
      }
    }

    // Consonant pileup repair (grapheme-aware)
    const wfc = config.writtenFormConstraints;
    const maxGraphemes = wfc?.maxConsonantGraphemes;
    if (maxGraphemes) {
      const before = context.trace ? cleanParts.join("") : "";
      repairConsonantPileups(cleanParts, hyphenatedParts, maxGraphemes, wfc?.consonantGraphemes);
      context.trace?.recordRepair("repairConsonantPileups", before, cleanParts.join(""));
    }

    // Feature-based junction validation (@backstop — Phase E of #250)
    // Since Phase A moved SSP validation upstream into adjustBoundary,
    // this write-phase repair should never fire. Retained as a safety net.
    if (syllables.length > 1) {
      const boundaries: SyllableBoundary[] = [];
      for (let si = 0; si < syllables.length - 1; si++) {
        const coda = syllables[si].coda;
        const nextOnset = syllables[si + 1].onset;
        boundaries.push({
          codaCluster: [...coda],
          onsetCluster: nextOnset,
        });
      }
      const beforeJunction = context.trace ? cleanParts.join("") : "";
      repairJunctions(cleanParts, hyphenatedParts, boundaries, config, wfc?.consonantGraphemes);
      if (context.trace) {
        const afterJunction = cleanParts.join("");
        if (afterJunction !== beforeJunction) {
          context.trace.recordRepair("repairJunctions:backstop", beforeJunction, afterJunction);
        }
      }
      // Re-run pileup repair in case junction repair changed things
      if (maxGraphemes) {
        const beforePileup = context.trace ? cleanParts.join("") : "";
        repairConsonantPileups(cleanParts, hyphenatedParts, maxGraphemes, wfc?.consonantGraphemes);
        context.trace?.recordRepair("repairConsonantPileups:postJunction", beforePileup, cleanParts.join(""));
      }
    }

    // Raw consonant letter backstop
    if (wfc?.maxConsonantLetters) {
      const before = context.trace ? cleanParts.join("") : "";
      repairConsonantLetters(cleanParts, hyphenatedParts, wfc.maxConsonantLetters);
      context.trace?.recordRepair("repairConsonantLetters", before, cleanParts.join(""));
    }

    // Word-final consonant letter limit
    if (wfc?.maxFinalConsonantLetters) {
      const before = context.trace ? cleanParts.join("") : "";
      repairFinalConsonantLetters(cleanParts, hyphenatedParts, wfc.maxFinalConsonantLetters);
      context.trace?.recordRepair("repairFinalConsonantLetters", before, cleanParts.join(""));
    }

    // Raw vowel letter backstop
    if (wfc?.maxVowelLetters) {
      const before = context.trace ? cleanParts.join("") : "";
      repairVowelLetters(cleanParts, hyphenatedParts, wfc.maxVowelLetters);
      context.trace?.recordRepair("repairVowelLetters", before, cleanParts.join(""));
    }

    // Post-join pass: apply word-scope spelling rules
    let finalClean = applySpellingRules(cleanParts.join(""), wordRules, rand, context.trace, "word");
    let finalHyphenated = hyphenatedParts.join("");

    // Post-join vowel repair for cross-boundary runs
    if (wfc?.maxVowelLetters) {
      let vResult = "";
      let vowelRun = 0;
      for (let ci = 0; ci < finalClean.length; ci++) {
        if (isVowelChar(finalClean[ci], ci, finalClean)) {
          vowelRun++;
          if (vowelRun <= wfc.maxVowelLetters) vResult += finalClean[ci];
        } else {
          vowelRun = 0;
          vResult += finalClean[ci];
        }
      }
      finalClean = vResult;
    }

    // Re-run consonant backstop after spelling rules (rules like ngx→nks can introduce new runs)
    if (wfc?.maxConsonantGraphemes || wfc?.maxConsonantLetters) {
      const postParts = [finalClean];
      const postHyph = [finalClean];
      const beforePost = context.trace ? finalClean : "";
      if (wfc.maxConsonantGraphemes) {
        repairConsonantPileups(postParts, postHyph, wfc.maxConsonantGraphemes, wfc.consonantGraphemes);
      }
      if (wfc.maxConsonantLetters) {
        repairConsonantLetters(postParts, postHyph, wfc.maxConsonantLetters);
      }
      if (wfc.maxFinalConsonantLetters) {
        repairFinalConsonantLetters(postParts, postHyph, wfc.maxFinalConsonantLetters);
      }
      finalClean = postParts[0];
      context.trace?.recordRepair("postSpellingBackstop", beforePost, finalClean);
    }

    if (tracing && context.trace) {
      const finalOwners = remapOwnersThroughRewrite(preRepairSurface, preRepairOwners, finalClean);
      context.trace.orthographyTrace = buildOrthographyTrace(finalClean, finalOwners, traceUnits, context.trace);
    }

    written.clean = finalClean;
    written.hyphenated = finalHyphenated;
  };
}
